<script setup lang="ts">
import type { ApiEnvelope } from '~/types/api'
import type { Page } from '~/types/billing'
const { can } = useAccess()
definePageMeta({layout:'admin',middleware:'management'})
const {request}=useApi()
interface Report {id:number;short_code:string;reason:string;status:string}
const {data,pending,error,refresh}=await useAsyncData('admin-reports',()=>request<ApiEnvelope<Page<Report>>>('admin/abuse-reports'))
const {data:links,refresh:refreshLinks}=await useAsyncData('admin-links',()=>request<ApiEnvelope<Page<{id:number;short_code:string;destination_url:string;is_active:boolean}>>>('admin/links'))
const failure=ref(''),busy=ref(false),confirming=ref<number|null>(null)
async function disable(){busy.value=true;try{await request(`admin/links/${confirming.value}/disable`,{method:'POST'});confirming.value=null;await refreshLinks()}catch{failure.value='Unable to disable link.'}finally{busy.value=false}}
</script>
<template><div><p class="eyebrow">Platform safety</p><h1 class="page-title mt-2">Moderation</h1><p class="mt-2 text-text-secondary">Review abuse reports and disable harmful short links.</p><p v-if="failure" class="mt-4 text-danger" role="alert">{{ failure }}</p><section class="surface mt-8 p-5"><h2 class="font-semibold">Recent abuse reports</h2><LoadingState v-if="pending"/><p v-else-if="error" role="alert">Reports could not be loaded. <button @click="refresh()">Retry</button></p><div v-for="report in data?.data.data" :key="report.id" class="flex justify-between border-b border-border py-4"><div><p class="font-medium">{{ report.short_code }}</p><p class="text-text-secondary">{{ report.reason }}</p></div><span class="badge-warning self-start">{{ report.status }}</span></div><p v-if="!data?.data.data.length" class="py-6 text-text-muted">No abuse reports.</p></section><section class="surface mt-6 overflow-x-auto"><table class="admin-table"><thead><tr><th>Recent links</th><th>Destination</th><th>Action</th></tr></thead><tbody><tr v-for="link in links?.data.data" :key="link.id"><td>{{ link.short_code }}</td><td class="max-w-md truncate">{{ link.destination_url }}</td><td><button v-if="can('moderation.manage') && link.is_active" class="text-danger" @click="confirming=link.id">Disable</button><span v-else class="badge-warning">{{ link.is_active?'Active':'Disabled' }}</span></td></tr></tbody></table></section><AdminDialog v-if="confirming" title="Disable this link?" @close="confirming=null"><p>The short link will stop redirecting. The destination and analytics will be retained.</p><button class="btn-danger mt-6" :disabled="busy" @click="disable">Disable link</button></AdminDialog></div></template>
